import { 
  MeshStandardNodeMaterial, 
  MeshBasicNodeMaterial,
  Color, 
  TorusKnotGeometry, 
  CylinderGeometry, 
  PlaneGeometry,
  Vector3
} from 'three/webgpu';
import { 
  texture, 
  uv, 
  vec3, 
  mix, 
  uniform, 
  time, 
  mul 
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, DirectionalLight, AmbientLight } = ctx.THREE;
  const mainGroup = new Group();
  const cleanupTasks = [];

  const palette = config.intent?.visualSpec?.colors ?? config.colors ?? {
    background: "#0b0b10",
    surface: "#14141a",
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    gradientStops: [{ at: 0, hex: "#0b0b10" }, { at: 0.7, hex: "#101017" }, { at: 1, hex: "#16161d" }]
  };

  // --- 1. BACKDROP ---
  const backdropGeo = new PlaneGeometry(12, 10);
  const backdropMat = new MeshBasicNodeMaterial();

  // Vertical gradient Node logic
  const vUv = uv();
  const stop0 = vec3(new Color(palette.gradientStops[0].hex));
  const stop1 = vec3(new Color(palette.gradientStops[1].hex));
  const stop2 = vec3(new Color(palette.gradientStops[2].hex));

  const gradColor = mix(
    stop0,
    mix(stop1, stop2, vUv.y.sub(0.7).max(0).div(0.3)),
    vUv.y.min(0.7).div(0.7)
  );

  backdropMat.colorNode = gradColor;
  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -3.0);
  mainGroup.add(backdropMesh);

  // --- 2. LOCAL LIGHTS (As requested by design doctrine for product shots)
  const keyLight = new DirectionalLight(0xffffff, 1.4);
  keyLight.position.set(2, 3, 2);
  mainGroup.add(keyLight);

  const rimLight = new DirectionalLight(new Color(palette.paper), 0.8);
  rimLight.position.set(-2, 2, -2);
  mainGroup.add(rimLight);

  const fillLight = new AmbientLight(0xffffff, 0.4);
  mainGroup.add(fillLight);

  // --- 3. PEDESTAL & SHADOWS ---
  const shadowGeo = new PlaneGeometry(3.0, 3.0);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const localUv = uv().sub(0.5).length();
  const shadowAlpha = mix(uniform(0.6), uniform(0.0), localUv.div(0.5).clamp());
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = shadowAlpha;

  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -0.36, 0);
  mainGroup.add(shadowMesh);

  // Pedestal geometry with chamfer logic built in (radial segments with high count, clean look)
  const pedestalGeo = new CylinderGeometry(1.1, 1.1, 0.5, 64);
  const pedestalMat = new MeshStandardNodeMaterial({
    color: new Color(palette.surface),
    roughness: 0.7,
    metalness: 0.35,
  });
  const pedestalMesh = new Mesh(pedestalGeo, pedestalMat);
  pedestalMesh.position.set(0, -0.6, 0); // top face sits ~ at y=-0.35
  mainGroup.add(pedestalMesh);

  // --- 4. HERO TORUS KNOT ---
  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshStandardNodeMaterial({
    color: new Color(palette.paper),
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    anisotropy: 0.9,
    anisotropyRotation: Math.PI / 2
  });

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      const texNode = texture(tex);
      // Roughness multiplier injection & breakup jitter via TSL Node graph
      const jitter = time.mul(8.0).sin().mul(0.02);
      knotMat.roughnessNode = mul(texNode.r, 0.9).add(0.55).add(jitter);
      knotMat.needsUpdate = true;
    });
  }

  const knotMesh = new Mesh(knotGeo, knotMat);
  knotMesh.position.set(0, 0.4, 0);
  mainGroup.add(knotMesh);

  // --- 5. TYPOGRAPHY & TEXT ---
  const textContainer = new Group();
  textContainer.position.set(0, 0, 0.1);
  mainGroup.add(textContainer);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  let headlineVerbatim = "Material study 03";
  let captionVerbatim = "GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT";

  items.forEach(item => {
    if (item.role === 'headline' || item.text?.includes('03')) {
      headlineVerbatim = item.text;
    } else if (item.role === 'caption' || item.text?.includes('TITANIUM')) {
      captionVerbatim = item.text;
    }
  });

  const headlineNode = ctx.fontAtlas.createText(headlineVerbatim, {
    fontSize: 0.24, // Scenic unit equivalent ~68px
    color: palette.paper,
    align: 'center'
  });
  headlineNode.position.set(0, -1.2, 0);
  textContainer.add(headlineNode);

  const captionNode = ctx.fontAtlas.createText(captionVerbatim, {
    fontSize: 0.08, // Scenic unit equivalent ~18px
    color: palette.accent,
    align: 'center',
    letterSpacingPx: 3
  });
  captionNode.position.set(0, -1.6, 0);
  textContainer.add(captionNode);

  // --- 6. ANIMATION & PRIMITIVES ---
  const spinTimeline = gsap.timeline({ repeat: -1 });
  spinTimeline.to(knotMesh.rotation, {
    y: Math.PI * 2,
    duration: 62.8, // roughly 0.1 rad/s
    ease: "none"
  });

  let primitiveCleanup = null;
  if (config.cinematicPrimitives && ctx.primitives) {
    const p = config.cinematicPrimitives.find(x => x.name === 'orbit');
    if (p) {
      const res = ctx.primitives['orbit'](mainGroup, p.params ?? { speed: 0.1, radius: 0.4 });
      if (res && res.cleanup) {
        primitiveCleanup = res.cleanup;
      }
    }
  }

  // --- 7. CLEANUP REGISTER ---
  mainGroup.userData.cleanup = function() {
    spinTimeline.kill();
    if (primitiveCleanup) primitiveCleanup();
    knotGeo.dispose();
    knotMat.dispose();
    pedestalGeo.dispose();
    pedestalMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
  };

  return mainGroup;
}
